+
+        var older = await ChatService.GetMessagesAsync(_selectedChannelId, _messages.Count, PageSize);
+        if (older.Count > 0)
+        {
+            _messages.InsertRange(0, older);
+            _threadSummaries = BuildThreadSummaries(_messages);
+        }
+
+        _isLoadingMore = false;
+    }
+
+    private async Task SendMessage(string content)
+    {
+        var msg = await ChatService.SendMessageAsync(_selectedChannelId, content, null);
+        _messages.Add(msg);
+    }
+
+    private async Task OpenThread(int messageId)
+    {
+        _threadRootMessage = _messages.FirstOrDefault(m => m.Id == messageId);
+        _threadReplies = await ChatService.GetThreadAsync(messageId);
+        _threadOpen = true;
+    }
+
+    private void CloseThread()
+    {
+        _threadOpen = false;
+        _threadRootMessage = null;
+        _threadReplies.Clear();
+    }
+
+    private async Task SendThreadReply(string content)
+    {
+        if (_threadRootMessage is null) return;
+        var reply = await ChatService.SendMessageAsync(_selectedChannelId, content, _threadRootMessage.Id);
+        _threadReplies.Add(reply);
+
+        // Update thread summary in main view
+        _threadSummaries = BuildThreadSummaries(_messages, _threadRootMessage.Id, _threadReplies.Count);
+    }
+
+    private async Task HandleReaction((int MessageId, string Emoji) args)
+    {
+        await ChatService.AddReactionAsync(args.MessageId, args.Emoji);
+        // Refresh messages to show updated reactions
+        _messages = await ChatService.GetMessagesAsync(_selectedChannelId, 0, _messages.Count);
+    }
+
+    private List<ThreadSummary> BuildThreadSummaries(List<Message> messages, int? updatedThreadId = null, int? updatedCount = null)
+    {
+        var rootIds = messages
+            .Where(m => m.ReplyToId is null)
+            .Select(m => m.Id)
+            .ToHashSet();
+
+        var summaries = messages
+            .Where(m => m.ReplyToId is not null && rootIds.Contains(m.ReplyToId.Value))
+            .GroupBy(m => m.ReplyToId!.Value)
+            .Select(g => new ThreadSummary(g.Key, g.Count(), g.Max(m => m.SentAt)))
+            .ToList();
+
+        if (updatedThreadId.HasValue && updatedCount.HasValue)
+        {
+            var existing = summaries.FirstOrDefault(s => s.RootMessageId == updatedThreadId.Value);
+            if (existing is not null)
+            {
+                summaries.Remove(existing);
+            }
+            summaries.Add(new ThreadSummary(updatedThreadId.Value, updatedCount.Value, DateTime.Now));
+        }
+
+        return summaries;
+    }
+}
