+    border-color: #7289da;
+    background: #36393f;
+}
+
+.thread-link {
+    background: none;
+    border: none;
+    color: #7289da;
+    font-size: 0.8rem;
+    cursor: pointer;
+    padding: 4px 0;
+    margin-top: 4px;
+}
+
+.thread-link:hover {
+    text-decoration: underline;
+}
+
+.message-actions {
+    position: absolute;
+    top: -8px;
+    right: 12px;
+    display: flex;
+    gap: 2px;
+    background: #2f3136;
+    border: 1px solid #4f545c;
+    border-radius: 4px;
+    padding: 2px;
+}
+
+.action-btn {
+    background: none;
+    border: none;
+    cursor: pointer;
+    padding: 4px 8px;
+    border-radius: 3px;
+    font-size: 1rem;
+}
+
+.action-btn:hover {
+    background: #36393f;
+}
+
+.emoji-picker {
+    position: absolute;
+    top: -40px;
+    right: 12px;
+    background: #2f3136;
+    border: 1px solid #4f545c;
+    border-radius: 6px;
+    padding: 6px;
+    display: flex;
+    gap: 4px;
+    z-index: 10;
+}
+
+.emoji-option {
+    background: none;
+    border: none;
+    font-size: 1.2rem;
+    cursor: pointer;
+    padding: 4px;
+    border-radius: 4px;
+}
+
+.emoji-option:hover {
+    background: #36393f;
+}
+
+/* Message input */
+.message-input {
+    padding: 12px 20px;
+    display: flex;
+    gap: 8px;
+    align-items: flex-end;
+    border-top: 1px solid #202225;
+}
+
+.message-input textarea {
+    flex: 1;
+    resize: none;
+    background: #40444b;
+    border: none;
+    border-radius: 8px;
+    padding: 10px 14px;
+    color: #dcddde;
+    font-size: 0.9rem;
+    font-family: inherit;
+    outline: none;
+}
+
+.message-input textarea::placeholder {
+    color: #72767d;
+}
+
+.send-btn {
+    background: #7289da;
+    color: #fff;
+    border: none;
+    border-radius: 6px;
+    padding: 10px 18px;
+    font-weight: 600;
+    cursor: pointer;
+    font-size: 0.85rem;
+}
+
+.send-btn:hover:not(:disabled) {
+    background: #677bc4;
+}
+
+.send-btn:disabled {
+    opacity: 0.5;
+    cursor: not-allowed;
+}
+
+/* Thread Panel */
+.thread-panel {
+    width: 25%;
+    min-width: 280px;
+    background: #2f3136;
+    color: #dcddde;
+    border-left: 1px solid #202225;
+    display: flex;
+    flex-direction: column;
+}
+
+.thread-header {
+    display: flex;
+    justify-content: space-between;
+    align-items: center;
+    padding: 12px 16px;
+    border-bottom: 1px solid #202225;
+}
+
+.thread-header h3 {
+    margin: 0;
+    font-size: 1rem;
+    color: #fff;
+}
+
+.close-btn {
+    background: none;
+    border: none;
+    color: #8e9297;
+    font-size: 1.2rem;
+    cursor: pointer;
+    padding: 4px 8px;
+    border-radius: 4px;
+}
+
+.close-btn:hover {
+    background: #36393f;
+    color: #fff;
+}
+
+.thread-root-message {
+    padding: 12px 16px;
+    background: #36393f;
+    border-bottom: 1px solid #202225;
+}
+
+.thread-root-message .message-content {
+    margin-top: 4px;
+}
+
+.thread-replies {
+    flex: 1;
+    overflow-y: auto;
+    padding: 12px 16px;
+    display: flex;
+    flex-direction: column;
+    gap: 8px;
+}
+
+.thread-reply {
+    padding: 6px 0;
+}
+

